import json, statistics
from pathlib import Path
import torch
from benchmarks.runners.compare_anthropic_a100 import fixture, capture, elapsed, metadata
from miniworld_engine.integrations import a100_families

@torch.no_grad()
def run(family,length):
    torch.manual_seed(191)
    model,inputs=fixture(family,length,'miniworld')
    model=model.cuda().bfloat16().eval()
    for name,p in model.named_parameters():
        if p.ndim>1:p.normal_(std=p.shape[-1]**-.5)
        elif name.endswith('weight'):p.normal_(mean=1,std=.1)
        else:p.normal_(std=.1)
    graphs={};outs={};orig=a100_families.serves
    try:
        for key in ['cuda','previous']:
            a100_families.serves=orig if key=='cuda' else lambda *a,**kw:False
            graphs[key],outs[key]=capture(model,inputs,'miniworld',8)
    finally:a100_families.serves=orig
    error=((outs['cuda'].float()-outs['previous'].float()).norm()/outs['previous'].float().norm()).item()
    assert error<.006,error
    samples={k:[] for k in graphs}
    for i in range(9):
        for k in (list(graphs) if i%2==0 else list(reversed(graphs))):samples[k].append(elapsed(graphs[k],10,8))
    result={'family':family,'length':length,'hardware':metadata(),'relative_error':error,'samples_ms':samples,
            'times_ms':{k:statistics.median(v) for k,v in samples.items()},
            'cuda_speedup':statistics.median(a/b for a,b in zip(samples['previous'],samples['cuda'],strict=True))}
    Path(f'/home/psk6950/miniworld-engine-scratch/codex_cuda_four/toggle_{family}_{length}.json').write_text(json.dumps(result,indent=2,default=str)+'\n')
    print(family,length,result['times_ms'],result['cuda_speedup'],flush=True)
for f in ['triattn_bidir_sa','triattn_bidir_bias','triattn_bias_start','triattn_bias_end']:
    for l in [128,768]:run(f,l)
